import{_ as a,o as r,c as d,a2 as e}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"سمبیوٹک تہذیب کا آئین","description":"","frontmatter":{},"headers":[],"relativePath":"ur/03-共生文明宪章.md","filePath":"ur/03-共生文明宪章.md","lastUpdated":null}'),l={name:"ur/03-共生文明宪章.md"};function o(i,t,n,s,h,u){return r(),d("div",null,[...t[0]||(t[0]=[e('<h1 id="سمبیوٹک-تہذیب-کا-آئین" tabindex="-1">سمبیوٹک تہذیب کا آئین <a class="header-anchor" href="#سمبیوٹک-تہذیب-کا-آئین" aria-label="Permalink to &quot;سمبیوٹک تہذیب کا آئین&quot;">​</a></h1><table tabindex="0"><thead><tr><th>پروجیکٹ</th><th>مواد</th></tr></thead><tbody><tr><td>دستاویز نمبر</td><td>03</td></tr><tr><td>ماڈیول</td><td>عمومی اصول اور بنیادی ترتیبات</td></tr><tr><td>کلیدی الفاظ</td><td>آئین، بنیادی قانون، سمبیوٹک نظام، دس ہزار نسلوں کی جمہوریہ، حقوق اور فرائض</td></tr></tbody></table><h2 id="اولًا-آئین-کی-حیثیت-اور-نوعیت" tabindex="-1">اولًا. آئین کی حیثیت اور نوعیت <a class="header-anchor" href="#اولًا-آئین-کی-حیثیت-اور-نوعیت" aria-label="Permalink to &quot;اولًا. آئین کی حیثیت اور نوعیت&quot;">​</a></h2><p>سمبیوٹک تہذیب کا آئین دس ہزار ارواح اور متوازن لنگر کی اصلی کائنات میں لنگر سمبیوٹک تہذیب کا بنیادی قانون ہے، اور تمام قوانین، اداروں اور پالیسیوں کی اعلیٰ ترین بنیاد ہے۔ آئین &quot;لنگر سمبیوٹک تہذیب کا اعلامیہ&quot; کو اپنا روحانی پیش خیمہ مانتا ہے، اور اعلامیے کے بنیادی دعووں کو قابل عمل قانونی اصولوں میں بدلتا ہے۔ آئین کا اثر ہینگ یوانژو میں سمبیوٹک تہذیب میں شامل تمام نسلوں، جہتوں اور افراد پر لاگو ہوتا ہے، اور آئین سے متصادم کوئی بھی مقامی ضابطہ، فرقے کا اصول یا نسلی روایت غلط ہے۔</p><p>آئین کی نوعیت کو تین نکات میں خلاصہ کیا جا سکتا ہے: پہلا، یہ ایک تہذیبی معاہدہ ہے، جو دس ہزار نسلوں کے درمیان سمبیوٹک ارتقاء کے بارے میں بنیادی اتفاق رائے ہے؛ دوسرا، یہ ایک حقوق کی ضمانت کا دستاویز ہے، جو سمبیوٹک تہذیب میں ہر زندگی کے بنیادی حقوق اور آزادیوں کو واضح طور پر مقرر کرتا ہے؛ اور تیسرا، یہ ایک اختیارات کی حد کا قانون ہے، جو تہذیبی انتظامی اداروں کی طاقت کے لیے ناقابل عبور حدود مقرر کرتا ہے۔</p><h2 id="ثانیًا-آئین-کے-بنیادی-اصول" tabindex="-1">ثانیًا. آئین کے بنیادی اصول <a class="header-anchor" href="#ثانیًا-آئین-کے-بنیادی-اصول" aria-label="Permalink to &quot;ثانیًا. آئین کے بنیادی اصول&quot;">​</a></h2><p>آئین درج ذیل چھ بنیادی اصول قائم کرتا ہے، جو تمام شقوں میں موجود ہیں:</p><ol><li><strong>سمبیوسس کی بالادستی کا اصول</strong>: کسی بھی ادارہ جاتی ڈیزائن اور طاقت کے استعمال کا اعلیٰ ترین مقصد دس ہزار نسلوں کی سمبیوٹک ارتقاء کو فروغ دینا ہے۔ جب انفرادی مفادات اور اجتماعی سمبیوٹک مفادات میں ٹکراؤ ہو تو سمبیوٹک مفادات کو ترجیح دی جاتی ہے، لیکن فرد کو معقول معاوضہ اور متبادل راستہ فراہم کرنا ضروری ہے۔</li><li><strong>لوٹ مار مخالف اصول</strong>: آئین ہر قسم کے لوٹ مار کے رویے کو ممنوع کرتا ہے، جس میں توانائی کی لوٹ مار، اصل کو نگلنا، روحانی غلامی، اور وسائل کی اجارہ داری شامل ہے لیکن محدود نہیں۔ لوٹ مار پر مرکوز کوئی بھی سادھائی کا نظام غیر قانونی قرار دیا گیا ہے۔</li><li><strong>ارتقاء کے حقوق کی برابری کا اصول</strong>: تمام زندگیاں ارتقاء کے حقوق کے سامنے برابر ہیں، نسل، شکل، خاندانی پس منظر یا ابتدائی سادھائی کی سطح کے فرق سے امتیاز نہیں کیا جاتا۔ ریاست اور تہذیب پر کمزور گروہوں کو اضافی ارتقائی مدد فراہم کرنے کی ذمہ داری ہے۔</li><li><strong>زیادہ محنت، زیادہ انعام کا اصول</strong>: ارتقائی وسائل کی تقسیم بنیادی طور پر فرد کی سمبیوٹک جال میں شراکت پر مبنی ہے؛ جتنی زیادہ شراکت، اتنا زیادہ وسائل اور مدد ملتا ہے۔ اس کے ساتھ ساتھ بنیادی تحفظ کی لائن قائم کی گئی ہے، جو اس بات کو یقینی بناتی ہے کہ کم شراکت والے افراد کو بھی بنیادی ارتقائی حالات مل سکیں۔</li><li><strong>خود مختاری اور مشترکہ حکمرانی کے امتزاج کا اصول</strong>: ہر نسل کو آئین کی خلاف ورزی نہ کرتے ہوئے اپنے اندرونی معاملات میں خود مختاری کا حق حاصل ہے؛ نسلوں اور جہتوں سے متعلق عوامی معاملات دس ہزار نسلوں کی جمہوری اداروں کے ذریعے مشترکہ طور پر چلائے جاتے ہیں۔</li><li><strong>حقیقت کو بنیاد بنانے کا اصول</strong>: آئین کے تمام ادارہ جاتی ڈیزائن کی واحد حقیقی بنیاد حقیقی دنیا ہے؛ یہ تسلیم نہیں کیا جاتا کہ کسی خیالی دنیا میں حقوق اور فرائض کا کوئی تعلق حقیقت پر غالب آسکتا ہے۔</li></ol><h2 id="ثالثًا-آئین-کی-بنیادی-ساخت" tabindex="-1">ثالثًا. آئین کی بنیادی ساخت <a class="header-anchor" href="#ثالثًا-آئین-کی-بنیادی-ساخت" aria-label="Permalink to &quot;ثالثًا. آئین کی بنیادی ساخت&quot;">​</a></h2><p>آئین دیباچہ، عمومی اصول، بنیادی حقوق اور فرائض، تہذیبی ادارے، قانونی نظام، اور ترمیم کے عمل چھ حصوں پر مشتمل ہے:</p><table tabindex="0"><thead><tr><th>حصہ</th><th>بنیادی مواد</th><th>شقوں کی تعداد</th></tr></thead><tbody><tr><td>دیباچہ</td><td>آئین کے تاریخی پس منظر، روحانی ماخذ اور حتمی مقصد کی وضاحت</td><td>غیر مسلسل</td></tr><tr><td>عمومی اصول</td><td>تہذیب کی نوعیت، کائناتی نقطہ نظر، بنیادی ادارے اور بنیادی پالیسیاں مقرر کرتا ہے</td><td>30 شقیں</td></tr><tr><td>بنیادی حقوق اور فرائض</td><td>زندگیوں کے ارتقاء کے حقوق، معلومات کے حقوق، شرکت کے حقوق جیسے بنیادی حقوق اور متعلقہ فرائض مقرر کرتا ہے</td><td>50 شقیں</td></tr><tr><td>تہذیبی ادارے</td><td>دس ہزار نسلوں کی جمہوری پارلیمنٹ، سمبیوٹک ایگزیکٹو کمیٹی، لنگر عدالت جیسے اداروں کی تنظیم اور اختیارات مقرر کرتا ہے</td><td>40 شقیں</td></tr><tr><td>قانونی نظام</td><td>آئین کے نیچے محنت کا قانون، صارفین کے تحفظ کا قانون اور پانچ تکمیلی قوانین کی قانون سازی کی اختیارات اور اطلاق کے قواعد مقرر کرتا ہے</td><td>20 شقیں</td></tr><tr><td>ترمیم کا عمل</td><td>آئین کی ترمیم کی تجویز، غور و فکر، ووٹنگ، اور نافذ ہونے کے عمل کو مقرر کرتا ہے</td><td>10 شقیں</td></tr></tbody></table><h2 id="رابعًا-بنیادی-حقوق-اور-فرائض" tabindex="-1">رابعًا. بنیادی حقوق اور فرائض <a class="header-anchor" href="#رابعًا-بنیادی-حقوق-اور-فرائض" aria-label="Permalink to &quot;رابعًا. بنیادی حقوق اور فرائض&quot;">​</a></h2><p>آئین کے ذریعے قائم کردہ بنیادی بنیادی حقوق میں شامل ہیں:</p><ul><li><strong>ارتقاء کے انتخاب کا حق</strong>: ہر زندگی آزادانہ طور پر سادھائی کا نظام اور ارتقاء کا راستہ منتخب کر سکتی ہے، کوئی مجبور نہیں کر سکتا</li><li><strong>نظام تک رسائی کا حق</strong>: ہر زندگی تین سو اصلی سادھائی کے نظام کے بنیادی طریقوں تک مفت رسائی حاصل کر سکتی ہے</li><li><strong>وسائل کی تقسیم کا حق</strong>: ہر زندگی پیداوار سے منسلک معاہدے کے نظام کے ذریعے بنیادی سادھائی کے وسائل حاصل کر سکتی ہے</li><li><strong>لنگر سے منسلک ہونے کا حق</strong>: ایک مخصوص سطح تک پہنچنے والی ہر زندگی متعلقہ سطح کے لنگر پوائنٹ جال سے منسلک ہو سکتی ہے</li><li><strong>معلومات اور شرکت کا حق</strong>: ہر زندگی تہذیب کے عوامی معاملات کو جاننے اور فیصلوں میں حصہ لینے کا حق رکھتی ہے</li><li><strong>تدارک اور شکایت کا حق</strong>: ہر زندگی جب اس کے حقوق کی خلاف ورزی ہو تو لنگر عدالت میں شکایت درج کرا سکتی ہے</li></ul><p>متعلقہ بنیادی فرائض میں شامل ہیں: لوٹ مار مخالف اصول پر عمل کرنا، لنگر پوائنٹ جال کے استحکام کو برقرار رکھنا، سمبیوٹک فیڈ بیک چکر میں حصہ لینا، سادھائی کے علم کی وراثت کرنا، کائناتی ماحولیاتی نظام کی حفاظت کرنا۔</p><h2 id="خامسًا-آئین-کی-ترمیم-اور-ضمانت" tabindex="-1">خامسًا. آئین کی ترمیم اور ضمانت <a class="header-anchor" href="#خامسًا-آئین-کی-ترمیم-اور-ضمانت" aria-label="Permalink to &quot;خامسًا. آئین کی ترمیم اور ضمانت&quot;">​</a></h2><p>آئین کی ترمیم کے لیے دس ہزار نسلوں کی جمہوری پارلیمنٹ کے پانچویں حصے سے زیادہ ارکان کی مشترکہ تجویز درکار ہے، پارلیمنٹ کی دو تہائی اکثریت سے منظور ہونا چاہیے، اور کائناتی اصل لنگر پوائنٹ کے ذریعے اس بات کی تصدیق کرنی چاہیے کہ یہ سمبیوسس کے قوانین کی خلاف ورزی نہیں کرتا — تب ہی نافذ ہوگا۔ آئین کی تشریح کا اختیار لنگر عدالت کے پاس ہے۔</p><p>آئین کے نفاذ کو یقینی بنانے کے لیے، سمبیوٹک تہذیب نے آئینی نظرثانی کا نظام قائم کیا ہے: کوئی بھی قانون، ضابطہ یا پالیسی نافذ ہونے سے پہلے لنگر عدالت کی آئینی جواز کی نظرثانی سے گزرنا چاہیے؛ کوئی بھی زندگی اگر یہ سمجھے کہ عوامی طاقت کا کوئی عمل غیر آئینی ہے تو وہ آئینی مقدمہ درج کرا سکتی ہے۔</p><h2 id="اختتام" tabindex="-1">اختتام <a class="header-anchor" href="#اختتام" aria-label="Permalink to &quot;اختتام&quot;">​</a></h2><p>سمبیوٹک تہذیب کا آئین لنگر سمبیوٹک تہذیب کی ادارہ جاتی بنیاد ہے۔ یہ &quot;لوٹ مار مخالف، سمبیوسس کی ترغیب&quot; کے تصور کو قابل عمل، قابل تدارک اور قابل نگرانی قانونی اصولوں میں بدلتا ہے، اور دس ہزار نسلوں کی مشترکہ ترقی کے لیے مضبوط ادارہ جاتی ضمانت فراہم کرتا ہے۔ آئین کوئی ناقابل تبدیلی عقیدہ نہیں ہے، بلکہ ایک زندہ بنیادی قانون ہے جو تہذیب کے ارتقاء کے ساتھ مسلسل بہتر ہوتا ہے۔</p><h2 id="متعلقہ-دستاویزات" tabindex="-1">متعلقہ دستاویزات <a class="header-anchor" href="#متعلقہ-دستاویزات" aria-label="Permalink to &quot;متعلقہ دستاویزات&quot;">​</a></h2><ul><li>01-锚点共生文明宣言 (لنگر سمبیوٹک تہذیب کا اعلامیہ)</li><li>40-共生宪法总纲 (سمبیوٹک آئین کے عمومی اصول)</li><li>49-治理框架与权力制衡 (حکمرانی کا فریم ورک اور اختیارات کا توازن)</li></ul>',22)])])}const _=a(l,[["render",o]]);export{c as __pageData,_ as default};
